#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <vector>

// One record: a length byte, that many payload bytes, and a checksum byte. A real format uses a
// wider length and a CRC; the shape and the recovery are the same.
using Bytes = std::vector<std::uint8_t>;

[[nodiscard]] std::uint8_t checksum_of(std::span<const std::uint8_t> payload) {
  std::uint8_t sum = 0;
  for (const std::uint8_t byte : payload) sum = static_cast<std::uint8_t>(sum + byte);
  return sum;
}

void append(Bytes& file, std::string_view payload) {
  const auto start = std::ssize(file);
  file.push_back(static_cast<std::uint8_t>(payload.size()));
  for (const char letter : payload) file.push_back(static_cast<std::uint8_t>(letter));
  file.push_back(checksum_of(std::span<const std::uint8_t>(file).subspan(static_cast<std::size_t>(start) + 1)));
}

// How many bytes at the front of the file are complete, checksummed records. Everything after
// that is what a torn write left behind, and the reader truncates it.
[[nodiscard]] std::int64_t good_prefix(std::span<const std::uint8_t> file) {
  std::int64_t good = 0;
  while (good < std::ssize(file)) {
    const std::int64_t length = file[static_cast<std::size_t>(good)];
    const std::int64_t end = good + 1 + length + 1;
    if (end > std::ssize(file)) break;  // the record is cut short
    const auto payload = file.subspan(static_cast<std::size_t>(good) + 1, static_cast<std::size_t>(length));
    if (checksum_of(payload) != file[static_cast<std::size_t>(end) - 1]) break;  // the record is damaged
    good = end;
  }
  return good;
}

[[nodiscard]] std::vector<std::string> records_in(std::span<const std::uint8_t> file) {
  std::vector<std::string> records;
  std::int64_t at = 0;
  while (at < std::ssize(file)) {
    const std::int64_t length = file[static_cast<std::size_t>(at)];
    std::string payload;
    for (std::int64_t i = 0; i < length; ++i) {
      payload.push_back(static_cast<char>(file[static_cast<std::size_t>(at + 1 + i)]));
    }
    records.push_back(payload);
    at += 1 + length + 1;
  }
  return records;
}

// Applying a record is idempotent: the sequence number says whether it has been applied already.
class Run {
 public:
  void apply(std::string_view record) {
    const std::int64_t seq = record[0] - '0';
    if (seq <= highest_) return;  // already applied, so a retry changes nothing
    highest_ = seq;
    ++applied_;
  }

  [[nodiscard]] std::string state() const { return std::format("{} records, highest seq {}", applied_, highest_); }

 private:
  std::int64_t applied_ = 0;
  std::int64_t highest_ = 0;
};

int main() {
  Bytes file;
  for (const std::string_view record : {"1:0.10", "2:0.20", "3:0.30"}) append(file, record);
  const auto complete = std::ssize(file);
  append(file, "4:0.40");
  file.resize(static_cast<std::size_t>(complete + 4));  // the card filled in the middle of record 4

  const std::int64_t good = good_prefix(file);
  std::cout << std::format("file {} bytes, good prefix {} bytes, torn tail {} bytes\n", std::ssize(file), good,
                           std::ssize(file) - good);

  const std::vector<std::string> recovered =
      records_in(std::span<const std::uint8_t>(file).subspan(0, static_cast<std::size_t>(good)));
  std::string names;
  for (const std::string& record : recovered) {
    if (!names.empty()) names += ", ";
    names += record;
  }
  std::cout << std::format("recovered: {}\n", names);

  Run run;
  for (const std::string& record : recovered) run.apply(record);
  std::cout << std::format("applied once:  {}\n", run.state());
  for (const std::string& record : recovered) run.apply(record);
  std::cout << std::format("applied twice: {}\n", run.state());
}
